import React from 'react';
import { Link } from 'react-router-dom';
import { format } from 'date-fns';

const EventCard = ({ event }) => {
    const eventDate = new Date(event.date);
    const isUpcoming = eventDate > new Date();
    const isAlmostSoldOut = event.availableSeats < 10 && event.availableSeats > 0;

    // Category color mapping
    const getCategoryColor = (category) => {
        const colors = {
            'Conference': 'bg-purple-100 text-purple-800',
            'Workshop': 'bg-blue-100 text-blue-800',
            'Seminar': 'bg-green-100 text-green-800',
            'Networking': 'bg-yellow-100 text-yellow-800',
            'Social': 'bg-pink-100 text-pink-800',
            'Other': 'bg-gray-100 text-gray-800'
        };
        return colors[category] || 'bg-gray-100 text-gray-800';
    };

    return (
        <div className="bg-white rounded-lg shadow-lg overflow-hidden hover:shadow-xl transition transform hover:-translate-y-1">
            <div className="h-48 bg-gradient-to-r from-purple-400 to-blue-400 flex items-center justify-center relative">
                <span className="text-6xl">🎉</span>
                {isAlmostSoldOut && (
                    <span className="absolute top-2 right-2 bg-red-500 text-white px-2 py-1 rounded-full text-xs font-bold">
                        Almost Sold Out!
                    </span>
                )}
            </div>
            
            <div className="p-6">
                <div className="flex justify-between items-start mb-2">
                    <h3 className="text-xl font-bold text-gray-800">{event.name}</h3>
                    <span className={`px-3 py-1 rounded-full text-sm ${
                        isUpcoming ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                    }`}>
                        {isUpcoming ? 'Upcoming' : 'Past'}
                    </span>
                </div>

                <p className="text-gray-600 mb-4 line-clamp-2">{event.description}</p>

                <div className="space-y-2 text-sm text-gray-600">
                    <div className="flex items-center">
                        <span className="mr-2">👤</span>
                        <span className="truncate">{event.organizer}</span>
                    </div>
                    <div className="flex items-center">
                        <span className="mr-2">📍</span>
                        <span className="truncate">{event.location}</span>
                    </div>
                    <div className="flex items-center">
                        <span className="mr-2">📅</span>
                        <span>{format(eventDate, 'PPP')} at {format(eventDate, 'p')}</span>
                    </div>
                    <div className="flex items-center">
                        <span className="mr-2">🎫</span>
                        <span className={isAlmostSoldOut ? 'text-red-600 font-bold' : ''}>
                            {event.availableSeats} / {event.capacity} seats available
                        </span>
                    </div>
                    <div className="flex items-center">
                        <span className="mr-2">🏷️</span>
                        <span className={`${getCategoryColor(event.category)} px-2 py-1 rounded text-xs font-semibold`}>
                            {event.category}
                        </span>
                    </div>
                </div>

                <Link
                    to={`/event/${event._id}`}
                    className="mt-6 block w-full bg-gradient-to-r from-purple-600 to-blue-600 text-white text-center py-3 rounded-lg hover:from-purple-700 hover:to-blue-700 transition font-semibold"
                >
                    View Details
                </Link>
            </div>
        </div>
    );
};

export default EventCard;
